"use strict";
/* 线代难点小讲义：中英两套，按语言取。
 *
 * 内容放在这里（会打包进静态预览版）；样式见 index.html 的 .notes-body / .note-*。
 * blocks 里每一项：字符串 = 段落；{h} 小标题；{ul} 项目符号；{formula} 公式块；
 * {tip} 提示块。内容是自己写的静态文案，直接当 HTML 用（所以 < 写成 &lt;）。
 *
 * 两种语言用同一个 id，切换语言时按 id 重画即可。
 */

// ---- 讲义交互图：在 Desmos 里嵌可拖拽 / 缩放的绘图计算器 --------------------
// 全篇共 14 张图（变换、特征值、基、相似、换基、点积、投影、Gram-Schmidt、
// 复特征值…），每张跟着对应讲义渲染。引擎是 Desmos，key 在
// web/desmos-config.js 配置（本地预览用官方 demo key，部署需填自己的免费 key）。
// 写图时记住 Desmos 的两个保留语义：变量名只能是单个字母（x1 会被当成多个变量、
// 直接报 "Too many variables"），"r=..." 会被当成极坐标方程画出一个圆。
// 图形数据存到 window.LA_NOTES._desmos，每个 DOM 节点用 data-desmos-idx 指向其中一项。
function _dx(latex, extra) { return Object.assign({ latex: latex }, extra || {}); }
// 渲染小工具：Desmos 里 bare "polygon(...)" 与参数曲线 "(x(t),y(t)){...}" 都会报警告、实际不画出来；
// 只有 \operatorname{polygon}(...)（线段/多边形）、点 (x,y)、显式方程才可靠渲染。所以：
//   _seg(x1,y1,x2,y2) 用 \operatorname{polygon} 画线段/向量；_fill(pts) 画填充多边形。
function _seg(x1, y1, x2, y2) {
  return "\\operatorname{polygon}((" + x1 + "," + y1 + "),(" + x2 + "," + y2 + "))";
}
function _fill(pts) {
  return "\\operatorname{polygon}(" + pts + ")";
}

// 线性变换：用滑块 a,b,c,d 操控矩阵 [[a,b],[c,d]]，看网格与基向量被怎么拉扯。
// 背景网格是原始坐标系；彩色平行四边形 = 单位正方形被变换后的像，|det A| = 它的面积。
function _desmosGridWarp() {
  var exps = [
    _dx("a=1", { id: "a", slider: { min: -2, max: 2, step: 0.1 } }),
    _dx("b=0.8", { id: "b", slider: { min: -2, max: 2, step: 0.1 } }),
    _dx("c=0", { id: "c", slider: { min: -2, max: 2, step: 0.1 } }),
    _dx("d=1", { id: "d", slider: { min: -2, max: 2, step: 0.1 } }),
    _dx(_fill("(0,0),(a,c),(a+b,c+d),(b,d)"), { id: "sq", color: "#4ea1ff", fillOpacity: 0.14 }),
    _dx(_seg(0, 0, 1, 0), { id: "e1", color: "#9aa4ae" }),
    _dx(_seg(0, 0, 0, 1), { id: "e2", color: "#9aa4ae" }),
    _dx(_seg(0, 0, "a", "c"), { id: "ae1", color: "#c74440" }),
    _dx(_seg(0, 0, "b", "d"), { id: "ae2", color: "#388c46" })
  ];
  for (var k = -3; k <= 3; k++) {
    if (k === 0) continue;
    exps.push(_dx("(x-(" + k + "*a))*d-(y-(" + k + "*c))*b=0", { id: "gv" + k }));
    exps.push(_dx("(x-(" + k + "*b))*c-(y-(" + k + "*d))*a=0", { id: "gh" + k }));
  }
  return {
    viewport: { xmin: -5, xmax: 5, ymin: -5, ymax: 5 },
    options: { expressionsCollapsed: true },
    expressions: exps
  };
}

// 特征值：固定矩阵 A = [[2,1],[1,2]]。红 / 绿两条线是特征方向所在（y=x / y=-x）：
// 红线上的 (1,1) 被 A 一乘只是沿红线拉长 3 倍，绿线上的 (1,-1) 的像仍落在绿线上。
// 灰色向量 (1,0) 的像（蓝）方向变了 —— 它就不是特征向量。
function _desmosEigen() {
  return {
    viewport: { xmin: -4, xmax: 4, ymin: -4, ymax: 4 },
    options: { expressionsCollapsed: true },
    expressions: [
      _dx("y=x", { id: "le1", color: "#c74440" }),
      _dx("y=-x", { id: "le2", color: "#388c46" }),
      _dx(_seg(0, 0, 1, 0), { id: "v1", color: "#9aa4ae" }),
      _dx(_seg(0, 0, 2, 1), { id: "v1i", color: "#2d70b3" }),
      _dx(_seg(0, 0, 1, 1), { id: "v2", color: "#c74440" }),
      _dx(_seg(0, 0, 3, 3), { id: "v2i", color: "#c74440" }),
      _dx(_seg(0, 0, 1, -1), { id: "v3", color: "#388c46" })
    ]
  };
}

// 基与维数：用滑块 a,b,c,d 定义向量 u=(a,b)、v=(c,d)，蓝平行四边形 = 它们张成的区域。
// 把 u、v 拖到共线（det=0）时，平行四边形塌成一条线 —— 这就是「线性相关、撑不满平面」。
function _desmosSpan() {
  return {
    viewport: { xmin: -4, xmax: 4, ymin: -4, ymax: 4 },
    options: { expressionsCollapsed: true },
    expressions: [
      _dx("a=1", { id: "a", slider: { min: -2, max: 2, step: 0.1 } }),
      _dx("b=1", { id: "b", slider: { min: -2, max: 2, step: 0.1 } }),
      _dx("c=2", { id: "c", slider: { min: -2, max: 2, step: 0.1 } }),
      _dx("d=-1", { id: "d", slider: { min: -2, max: 2, step: 0.1 } }),
      _dx(_fill("(0,0),(a,b),(a+c,b+d),(c,d)"), { id: "sp", color: "#4ea1ff", fillOpacity: 0.18 }),
      _dx(_seg(0, 0, "a", "b"), { id: "u", color: "#c74440" }),
      _dx(_seg(0, 0, "c", "d"), { id: "v", color: "#388c46" })
    ]
  };
}

// 正交变换（旋转）：旋转矩阵 R(θ)=[[cosθ,−sinθ],[sinθ,cosθ]] 保持长度与角度不变。
// 灰 = 原基向量 e₁,e₂ 与向量 v；红/绿/蓝虚线 = 旋转后的像。拖 θ 看整组绕原点刚性转动。
function _desmosRotate() {
  return {
    viewport: { xmin: -2.5, xmax: 2.5, ymin: -2.5, ymax: 2.5 },
    options: { expressionsCollapsed: true, degreeMode: true },
    expressions: [
      _dx("k=30", { id: "k", slider: { min: 0, max: 360, step: 5 } }),
      _dx("x^2+y^2=1", { id: "circ", color: "#c9d1d9", lineOpacity: 0.3 }),
      _dx(_seg(0, 0, 1, 0), { id: "e1", color: "#9aa4ae" }),
      _dx(_seg(0, 0, 0, 1), { id: "e2", color: "#9aa4ae" }),
      _dx(_seg(0, 0, "\\cos(k)", "\\sin(k)"), { id: "re1", color: "#c74440" }),
      _dx(_seg(0, 0, "\\cos(k+90)", "\\sin(k+90)"), { id: "re2", color: "#388c46" }),
      _dx(_seg(0, 0, "\\cos(45)", "\\sin(45)"), { id: "v", color: "#2d70b3" }),
      _dx(_seg(0, 0, "\\cos(k+45)", "\\sin(k+45)"), { id: "rv", color: "#2d70b3", lineStyle: "DASHED" })
    ]
  };
}

// det = 0 → 平面塌成线：A=[[1,1],[0,b]]，det(A)=b，两列 c₁=(1,0)、c₂=(1,b)。
// 初始 b=1 是一个清清楚楚的平行四边形（det=1）；把 b 拖到 0，c₂ 和 c₁ 共线，
// 平行四边形塌成一条线段（面积 0）——降维、信息丢、不可逆。
function _desmosCollapse() {
  return {
    viewport: { xmin: -1.6, xmax: 3.2, ymin: -2.2, ymax: 2.2 },
    options: { expressionsCollapsed: true },
    expressions: [
      _dx("b=1", { id: "b", slider: { min: -1.5, max: 1.5, step: 0.1 } }),
      _dx(_fill("(0,0),(1,0),(2,b),(1,b)"), { id: "par", color: "#4ea1ff", fillOpacity: 0.18 }),
      _dx(_seg(0, 0, 1, 0), { id: "c1", color: "#c74440" }),
      _dx(_seg(0, 0, 1, "b"), { id: "c2", color: "#388c46" })
    ]
  };
}

// 三个空间里的两个：A=[[1,1],[1,1]] 的列空间与零空间。蓝线 = Col(A)（一切像都落在 y=x），
// 粗蓝段是单位正方形的像；红线 = Nul(A)（y=−x 上的向量被压成 0）。
function _desmosSubspaces() {
  return {
    viewport: { xmin: -3, xmax: 3, ymin: -3, ymax: 3 },
    options: { expressionsCollapsed: true },
    expressions: [
      _dx("y=x", { id: "col", color: "#4ea1ff" }),
      _dx("y=-x", { id: "nul", color: "#c74440" }),
      _dx(_seg(0, 0, 2, 2), { id: "img", color: "#2d70b3", lineWidth: 6 }),
      _dx(_seg(0, 0, 1, -1), { id: "kv", color: "#c74440" }),
      _dx("(1,1)", { id: "colpt", color: "#388c46", pointStyle: "OPEN" })
    ]
  };
}

// 相似 / 对角化：A=[[4,1],[2,3]]，特征值 5（方向 (1,1)）与 2（方向 (1,−2)）。
// 实线 = 向量 x，虚线 = 它的像 A·x。像始终留在同一条特征线上，只是长度变成 5 倍 / 2 倍
// —— 在特征基下 A 就是 diag(5,2)，这正是 A ~ diag(5,2)。
function _desmosSimilar() {
  return {
    viewport: { xmin: -2, xmax: 6.5, ymin: -5.5, ymax: 6.5 },
    options: { expressionsCollapsed: true },
    expressions: [
      _dx("t=1", { id: "t", slider: { min: 0.2, max: 1.2, step: 0.1 } }),
      _dx("y=x", { id: "l1", color: "#9aa4ae", lineOpacity: 0.35 }),
      _dx("y=-2x", { id: "l2", color: "#9aa4ae", lineOpacity: 0.35 }),
      _dx(_seg(0, 0, "5t", "5t"), { id: "i1", color: "#c74440", lineStyle: "DASHED", lineWidth: 4 }),
      _dx(_seg(0, 0, "2t", "-4t"), { id: "i2", color: "#388c46", lineStyle: "DASHED", lineWidth: 4 }),
      _dx(_seg(0, 0, "t", "t"), { id: "v1", color: "#c74440", lineWidth: 4 }),
      _dx(_seg(0, 0, "t", "-2t"), { id: "v2", color: "#388c46", lineWidth: 4 })
    ]
  };
}

// 特征方程：把 det(A−λI) 当成 λ 的函数画出来，就是一条抛物线 y=(x−2)(x−5)
// （A=[[4,1],[2,3]]）。拖动 λ 探针 m：只有 m=2 或 5 时点才落在横轴上，
// 也就是 det(A−λI)=0 的两个位置 ——「特征值 = 特征多项式的零点」一眼可见。
function _desmosCharPoly() {
  return {
    viewport: { xmin: -1, xmax: 7, ymin: -5, ymax: 15 },
    options: { expressionsCollapsed: true },
    expressions: [
      _dx("m=1", { id: "m", slider: { min: 0, max: 6, step: 0.1 } }),
      _dx("y=(x-2)(x-5)", { id: "poly", color: "#4ea1ff", lineWidth: 3 }),
      _dx("y=0", { id: "axis", color: "#9aa4ae", lineOpacity: 0.4 }),
      _dx(_seg("m", 0, "m", "(m-2)(m-5)"), { id: "drop", color: "#9aa4ae", lineStyle: "DASHED" }),
      _dx("(m,(m-2)(m-5))", { id: "probe", color: "#c74440", pointSize: 12 }),
      _dx("(2,0)", { id: "r1", color: "#388c46", pointSize: 10 }),
      _dx("(5,0)", { id: "r2", color: "#388c46", pointSize: 10 })
    ]
  };
}

// 对角化最实用的结论 Aᵏ = P·Dᵏ·P⁻¹：取 A=[[1,1],[0,2]]（λ=1 方向 y=0，λ=2 方向 y=x）。
// 把 u=(2,1) 拆成两个特征方向之和 (1,0)+(1,1)，则 Aᵏu = 1ᵏ(1,0) + 2ᵏ(1,1)。
// 拖整数 k：绿色分量沿 y=x 按 2ᵏ 变长、红色分量原地不动，蓝色一般向量的像方向随之偏转
// ——「换到特征基 → 各方向各自取幂 → 换回来」一眼可见。
function _desmosMatrixPower() {
  return {
    viewport: { xmin: -1, xmax: 6.5, ymin: -1, ymax: 6.5 },
    options: { expressionsCollapsed: true },
    expressions: [
      _dx("k=2", { id: "k", slider: { min: 0, max: 2, step: 1 } }),
      _dx("y=x", { id: "l2", color: "#9aa4ae", lineOpacity: 0.12 }),
      _dx(_fill("(0,0),(1,0),(2,1),(1,1)"), { id: "sq", color: "#4ea1ff", fillOpacity: 0.1 }),
      _dx(_seg(0, 0, 1, 0), { id: "v1", color: "#c74440", lineWidth: 3 }),
      _dx(_seg(0, 0, 1, 1), { id: "v2", color: "#388c46", lineWidth: 3 }),
      _dx(_seg(0, 0, 2, 1), { id: "u", color: "#2d70b3", lineWidth: 3 }),
      _dx("(1,0)", { id: "p1", color: "#c74440", pointSize: 9 }),
      _dx("(1,1)", { id: "p2", color: "#388c46", pointSize: 9 }),
      _dx("(2,1)", { id: "pu", color: "#2d70b3", pointSize: 9 }),
      _dx(_seg(0, 0, "2^k", "2^k"), { id: "v2k", color: "#388c46", lineWidth: 5, lineStyle: "DASHED" }),
      _dx(_seg(0, 0, "1+2^k", "2^k"), { id: "uk", color: "#2d70b3", lineWidth: 5, lineStyle: "DASHED" })
    ]
  };
}

// 换基：同一个向量 x=(p,q)，标准基分解（灰虚线）与斜基 B={(1,1),(1,−1)} 分解
// （红 b₁ 分量 + 绿 b₂ 分量）同时画出。B 坐标 c₁=(p+q)/2、c₂=(p−q)/2。
// 全部用可靠的 \operatorname{polygon} 线段 + 点 + 显式方程；滑块只用拉丁字母。
function _desmosChangeBasis() {
  var c1 = "p/2+q/2";
  return {
    viewport: { xmin: -3, xmax: 6, ymin: -4, ymax: 5 },
    options: { expressionsCollapsed: true },
    expressions: [
      _dx("p=3", { id: "p", slider: { min: -2, max: 4, step: 1 } }),
      _dx("q=1", { id: "q", slider: { min: -2, max: 4, step: 1 } }),
      _dx("y=x", { id: "l1", color: "#9aa4ae", lineOpacity: 0.12 }),
      _dx("y=-x", { id: "l2", color: "#9aa4ae", lineOpacity: 0.12 }),
      _dx(_seg(0, 0, "p", "0"), { id: "s1", color: "#9aa4ae", lineWidth: 2, lineStyle: "DASHED" }),
      _dx(_seg("p", "0", "p", "q"), { id: "s2", color: "#9aa4ae", lineWidth: 2, lineStyle: "DASHED" }),
      _dx(_seg(0, 0, c1, c1), { id: "b1", color: "#c74440", lineWidth: 4 }),
      _dx(_seg(c1, c1, "p", "q"), { id: "b2", color: "#388c46", lineWidth: 4 }),
      _dx(_seg(0, 0, "p", "q"), { id: "x", color: "#2d70b3", lineWidth: 3 }),
      _dx("(p,q)", { id: "xp", color: "#2d70b3", pointSize: 10 }),
      _dx("(" + c1 + "," + c1 + ")", { id: "mid", color: "#c74440", pointSize: 9 })
    ]
  };
}

// 点积与投影：u=(2,1) 固定，v=(p,q) 可拖。系数 c=(u·v)/(u·u)=(2p+q)/5，
// 绿色向量 c·u=(2c,c) 就是 v 在 u 方向上的投影；灰色虚线是垂直误差 b−p。
// 拖 p、q 看 c 跟着变：同向时投影长、垂直时投影缩成 0、反向时投影翻到 u 背后。
function _desmosDotProduct() {
  return {
    viewport: { xmin: -1, xmax: 5, ymin: -2, ymax: 4 },
    options: { expressionsCollapsed: true },
    expressions: [
      _dx("p=3", { id: "p", slider: { min: -2, max: 4, step: 0.1 } }),
      _dx("q=1", { id: "q", slider: { min: -2, max: 4, step: 0.1 } }),
      _dx("c=(2p+q)/5"),
      _dx("y=0.5x", { id: "guide", color: "#9aa4ae", lineOpacity: 0.12 }),
      _dx(_seg(0, 0, 2, 1), { id: "u", color: "#c74440", lineWidth: 4 }),
      _dx("(2,1)", { id: "up", color: "#c74440", pointSize: 9 }),
      _dx(_seg(0, 0, "p", "q"), { id: "v", color: "#2d70b3", lineWidth: 3 }),
      _dx("(p,q)", { id: "vp", color: "#2d70b3", pointSize: 9 }),
      _dx(_seg(0, 0, "2c", "c"), { id: "proj", color: "#388c46", lineWidth: 4 }),
      _dx("(2c,c)", { id: "pp", color: "#388c46", pointSize: 9 }),
      _dx(_seg("2c", "c", "p", "q"), { id: "err", color: "#9aa4ae", lineStyle: "DASHED", lineOpacity: 0.35 })
    ]
  };
}

// 正交投影：直线 L 的方向 u=(1,m)，m 可拖；b=(3,1) 固定。
// c=(u·b)/(u·u)=(3+m)/(1+m²)，p=c·u=(c,cm) 是投影，红虚线 e=b−p 永远与 L 垂直。
// 拖 m 改变直线斜率：投影点沿 L 滑动，误差方向始终和 L 成直角。
function _desmosProjection() {
  return {
    viewport: { xmin: -2, xmax: 5, ymin: -3, ymax: 4 },
    options: { expressionsCollapsed: true },
    expressions: [
      _dx("m=1", { id: "m", slider: { min: -2, max: 2, step: 0.1 } }),
      _dx("c=(3+m)/(1+m^2)"),
      _dx("y=mx", { id: "L", color: "#9aa4ae", lineOpacity: 0.18 }),
      _dx(_seg(0, 0, 3, 1), { id: "b", color: "#2d70b3", lineWidth: 3 }),
      _dx("(3,1)", { id: "bp", color: "#2d70b3", pointSize: 10 }),
      _dx(_seg(0, 0, "c", "c*m"), { id: "p", color: "#388c46", lineWidth: 4 }),
      _dx("(c,c*m)", { id: "pp", color: "#388c46", pointSize: 9 }),
      _dx(_seg("c", "c*m", 3, 1), { id: "e", color: "#c74440", lineWidth: 3, lineStyle: "DASHED" })
    ]
  };
}

// Gram-Schmidt：b₁=a₁=(2,1) 固定，a₂=(p,q) 可拖。
// c=(a₂·b₁)/(b₁·b₁)=(2p+q)/5，投影是 (2c,c)；减掉它剩下的 b₂=(p−2c,q−c)
// 就是绿色的新基向量。拖 p、q：b₂ 会跟着转，但始终和 b₁ 垂直 —— 这就是正交化。
function _desmosGramSchmidt() {
  return {
    viewport: { xmin: -3, xmax: 4, ymin: -2, ymax: 4 },
    options: { expressionsCollapsed: true },
    expressions: [
      _dx("p=1", { id: "p", slider: { min: -3, max: 4, step: 0.1 } }),
      _dx("q=2", { id: "q", slider: { min: -3, max: 4, step: 0.1 } }),
      _dx("c=(2p+q)/5"),
      _dx("y=0.5x", { id: "guide", color: "#9aa4ae", lineOpacity: 0.12 }),
      _dx(_seg(0, 0, 2, 1), { id: "b1", color: "#c74440", lineWidth: 4 }),
      _dx("(2,1)", { id: "b1p", color: "#c74440", pointSize: 9 }),
      _dx(_seg(0, 0, "p", "q"), { id: "a2", color: "#2d70b3", lineWidth: 3 }),
      _dx("(p,q)", { id: "a2p", color: "#2d70b3", pointSize: 9 }),
      // 投影段和 b₁ 同方向、会完全压在红向量上：换成醒目橙色虚线 + 末端空心点，
      // 否则读者只看见一条红线段、找不到 caption 里说的「投影」。
      _dx(_seg(0, 0, "2c", "c"), { id: "proj", color: "#a8621c", lineWidth: 3, lineStyle: "DASHED", lineOpacity: 0.85 }),
      _dx("(2c,c)", { id: "projpt", color: "#a8621c", pointSize: 9, pointStyle: "OPEN" }),
      _dx(_seg("2c", "c", "p", "q"), { id: "b2shift", color: "#388c46", lineWidth: 2, lineStyle: "DASHED", lineOpacity: 0.5 }),
      _dx(_seg(0, 0, "p-2c", "q-c"), { id: "b2", color: "#388c46", lineWidth: 4 }),
      _dx("(p-2c,q-c)", { id: "b2p", color: "#388c46", pointSize: 9 })
    ]
  };
}

// 复特征值：A = [[a,−b],[b,a]]。它做的事只有两件 —— 逆时针转 θ = atan2(b,a)，
// 再把长度乘 r = √(a²+b²)。b=0 时退化成纯缩放（有实特征值）；b≠0 时判别式 −4b² < 0，
// 没有实的特征方向，只能转。橙色折线是 (1,0) 被反复作用：r<1 向内旋、r=1 原地打转、
// r>1 向外旋，这正是 Aᵏ 的三种命运。
function _desmosComplexEigen() {
  return {
    // 图的宽高比约 1.76:1；Desmos 会严格按 viewport 铺满容器，所以 x 区间要给
    // 成 y 区间的 1.76 倍，单位长度才是正方形。否则「转 36.9°」会被横向拉成 55°，
    // 而这张图讲的就是角度。
    viewport: { xmin: -3, xmax: 3, ymin: -1.7, ymax: 1.7 },
    options: { expressionsCollapsed: true },
    expressions: [
      _dx("a=0.8", { id: "a", slider: { min: -1.5, max: 1.5, step: 0.05 } }),
      _dx("b=0.6", { id: "b", slider: { min: -1.5, max: 1.5, step: 0.05 } }),
      // 别用 r 当变量名：Desmos 把 "r=..." 当成极坐标方程，会额外画一个圆。
      _dx("k=\\sqrt{a^2+b^2}"),
      // 变量名只能是单个字母：写成 x1 / y1 会被 Desmos 当成「多个变量」直接报错。
      _dx("m=a^2-b^2"),
      _dx("n=2*a*b"),
      _dx("p=a*m-b*n"),
      _dx("q=b*m+a*n"),
      // 单位正方形被 A 作用后的像：还是正方形，只是转了 θ、放大了 r 倍。
      _dx(_fill("(0,0),(a,b),(a-b,a+b),(-b,a)"), { id: "sq", color: "#4ea1ff", fillOpacity: 0.12 }),
      _dx(_seg(0, 0, 1, 0), { id: "v0", color: "#9aa4ae", lineWidth: 2 }),
      _dx("(1,0)", { id: "v0p", color: "#9aa4ae", pointSize: 7 }),
      _dx(_seg(0, 0, "a", "b"), { id: "v1", color: "#c74440", lineWidth: 3 }),
      _dx("(a,b)", { id: "v1p", color: "#c74440", pointSize: 8 }),
      // 首尾相接的虚线：v → Av → A²v → A³v。r 偏离 1 时它就卷成螺旋。
      _dx(_seg(1, 0, "a", "b"), { id: "t1", color: "#a8621c", lineWidth: 2, lineStyle: "DASHED", lineOpacity: 0.75 }),
      _dx(_seg("a", "b", "m", "n"), { id: "t2", color: "#a8621c", lineWidth: 2, lineStyle: "DASHED", lineOpacity: 0.75 }),
      _dx(_seg("m", "n", "p", "q"), { id: "t3", color: "#a8621c", lineWidth: 2, lineStyle: "DASHED", lineOpacity: 0.75 }),
      _dx("(m,n)", { id: "v2p", color: "#a8621c", pointSize: 7 }),
      _dx("(p,q)", { id: "v3p", color: "#a8621c", pointSize: 7 })
    ]
  };
}

