      lead: "同一个特征值，为什么有时能撑起两条独立特征向量、有时只剩一条？区别就藏在两个「重数」里。这篇把代数重数 AM 和几何重数 GM 讲清楚，并说明它俩如何一句话决定矩阵能不能对角化。",
