          "主元个数 = 这些向量张成的维数（也就是秩）。",
          "主元个数 = 向量个数 → 线性无关，它们就是自己所张成空间的基。",
          "主元个数 &lt; 向量个数 → 有冗余，不是基，需要去掉多余的。",
